/**
 * Puts the window into each state the README shows, one after another.
 *
 * `scripts/screenshots.py` is the other half: it launches a check build with
 * `TPDF_OPENCHECK=screenshots:<demo.pdf>|<signed.pdf>|<regions>|<sample.pdf>`, reads this
 * phase's transcript as it is written, and captures the window each time a
 * `SHOT <name>` line appears. So the pictures in `docs/img/` are regenerated by
 * one command and show the application as it is, not as it was when somebody
 * last pressed a key combination.
 *
 * **The window holds each state for {@link HOLD_MS}**, which is the whole
 * protocol: the webview cannot be told when the capture finished, and a file
 * to wait on would need a command only this phase used.
 *
 * Every held state is also a frame of `docs/img/demo.gif`: the line is
 * `FRAME <index> <milliseconds shown> [<still name>]`, and the six that carry
 * a name are the stills. The frames between them are the steps a still skips
 * --- the palette being typed into, the marks arriving one at a time --- so
 * the animation is the same run, not a second script that could show
 * something the stills do not.
 *
 * Marks and regions go through `host.apply`, the application's own edit path,
 * and not through the model alone: the first run marked the model, every check
 * was green, and the pictures showed an untouched page beside an empty list.
 */

import { pause, settle, type Report } from "./checkreport";
import { isMac } from "./keys";
import type { OpenCheckHost } from "./opencheck";
import { DIALOG_CLASS as PRINT_PREVIEW } from "./printpreviewdialog";

/** How long each state stays on screen for the capture. */
const HOLD_MS = 1200;
const SETTLE_MS = 20_000;

type Region = [number, number, number, number];

export async function screenshotCheck(
  host: OpenCheckHost,
  expected: string,
  report: Report,
): Promise<void> {
  const [demo, signed, encoded, sample, more] = expected.split("|");
  if (!demo || !signed || !encoded || !sample) {
    throw new Error("the demo document, a signed document, the regions and the sample letter are required");
  }
  const regions = JSON.parse(encoded) as Record<string, Region>;
  const region = (name: string): Region => {
    const found = regions[name];
    if (!found) throw new Error(`no region named ${name}`);
    return found;
  };
  const quiet = async () => {
    if (!(await settle(() => host.viewer()?.idle === true, SETTLE_MS))) {
      throw new Error("the viewer did not settle");
    }
    await pause(300);
  };
  let frames = 0;
  /** Holds the window as it is; `shown` is how long the animation stays on it. */
  const frame = async (shown: number, still = "") => {
    await quiet();
    report.emit(`FRAME ${frames++} ${shown} ${still}`.trimEnd());
    await pause(HOLD_MS);
  };
  const shot = async (name: string, shown = 1800) => {
    await frame(shown, name);
    report.check(`held the window for ${name}`, true, "");
  };

  // ---- Reading: the document, its pages beside it.
  await host.open(demo); await host.idle(); await quiet();
  host.run("view.showThumbnails"); await host.idle();
  host.viewer()!.setFit("width");
  await shot("reading");

  // ---- The command palette, mid-question.
  const button = [...document.querySelectorAll<HTMLButtonElement>("button")].find(
    (b) => b.textContent === "Commands",
  );
  if (!button) throw new Error("the toolbar has no Commands button");
  button.click();
  const field = () => document.querySelector<HTMLInputElement>(".tpdf-palette input");
  if (!(await settle(() => field() !== null && field()!.offsetParent !== null, 5000))) {
    throw new Error("the palette did not open");
  }
  await frame(500);
  // Typed a letter at a time for the animation; the still is the last one.
  for (const typed of ["r", "re", "red", "reda", "redac"]) {
    field()!.value = typed;
    field()!.dispatchEvent(new InputEvent("input", { bubbles: true }));
    await frame(160);
  }
  field()!.value = "redact";
  field()!.dispatchEvent(new InputEvent("input", { bubbles: true }));
  await shot("palette");
  field()!.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));
  await pause(200);

  // ---- Marks: a highlight, a box and a comment, listed in the sidebar.
  const model = host.edits()!;
  const page = model.state.pages[0]!.id;
  host.run("view.showMarks"); await host.idle();
  await host.apply((e) => e.mark("highlight", page, region("highlight")));
  await host.idle(); await frame(800);
  await host.apply((e) => e.mark("square", page, region("box")));
  await host.idle(); await frame(800);
  await host.apply((e) =>
    e.mark("note", page, region("note"), [], "North Pier is above the design level."));
  await host.idle();
  report.check("three marks reached the model", host.edits()!.state.marks.length === 3,
    String(host.edits()!.state.marks.length));
  await shot("annotate");

  // ---- Redaction: two regions marked and listed, nothing removed yet.
  host.run("view.showRedactions"); await host.idle();
  await host.apply((e) => e.redact(page, region("redact_name")));
  await host.idle(); await frame(800);
  await host.apply((e) => e.redact(page, region("redact_mail")));
  await host.idle();
  report.check("two regions reached the review list", host.edits()!.state.redactions.length === 2,
    String(host.edits()!.state.redactions.length));
  await shot("redact");

  if (more === "more") await moreStates(host, shot, report);

  // ---- A letter somebody else redacted with black boxes: the words they left
  // in the file, listed. The page beside the list still shows only the boxes.
  await host.open(sample); await host.idle(); await quiet();
  host.viewer()!.setFit("width");
  host.run("file.findHiddenText");
  const passages = () =>
    document.querySelectorAll('[aria-label="Text the pages do not show"] button').length;
  if (!(await settle(() => passages() > 0, SETTLE_MS))) {
    throw new Error("the check for text the pages do not show listed nothing");
  }
  report.check("the sample letter's four covered passages are listed", passages() === 4,
    String(passages()));
  await shot("hidden", 2600);

  // ---- Signatures: a document two people signed, one card each.
  await host.open(signed); await host.idle(); await quiet();
  host.run("file.properties");
  const cards = () => document.querySelectorAll<HTMLDetailsElement>(".tpdf-properties details");
  if (!(await settle(() => cards().length > 1, SETTLE_MS))) {
    throw new Error("the properties dialog showed no signature cards");
  }
  // Both closed: two cards on one screen is what the picture is of, and an
  // open one pushes the other out of sight.
  await shot("signatures");
  // And one opened, which only the animation shows.
  cards()[0]!.open = true;
  await frame(2600);

  if (more === "more") {
    // What signing asks, of a document with nothing unsaved. The properties
    // dialog is put away first: it is a dialog too.
    const close = [...document.querySelectorAll<HTMLButtonElement>(".tpdf-properties button")]
      .find((b) => /^(Close|Done)$/.test((b.textContent ?? "").trim()));
    // Escape is listened for on the dialog's own backdrop, so it is sent from inside.
    if (close) close.click();
    else openDialog()?.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));
    const put = await settle(() => openDialog() === undefined, 3000);
    report.check("the properties dialog was put away before signing was asked", put, "");
    await photographDialog(host, report, shot, "file.signDocument", "sign");
  }
}

/** The dialog on screen, if there is one. */
function openDialog(): HTMLElement | undefined {
  // A `<dialog>` is in the document while it is closed, and one that is open
  // has no `offsetParent`, being in the top layer.
  return [...document.querySelectorAll<HTMLElement>('[role="dialog"], dialog')]
    .find((dialog) => dialog instanceof HTMLDialogElement ? dialog.open : dialog.offsetParent !== null);
}

/**
 * Runs a command, photographs the dialog it opens, and closes it unanswered.
 *
 * A command that answers with a message and no dialog is recorded with what
 * it said, and passes: which of the two it does is what is being looked at.
 * `ready` is what the dialog must show before it is photographed, for one
 * whose content arrives after it opens.
 */
async function photographDialog(
  host: OpenCheckHost,
  report: Report,
  shot: (name: string) => Promise<void>,
  id: string,
  name: string,
  ready?: () => boolean,
): Promise<void> {
  host.run(id);
  const shown = await settle(() => openDialog() !== undefined, 6000);
  const said = document.querySelector('[data-testid="problem"] p.error, [data-testid="notice"]')?.textContent ?? "";
  const dialog = openDialog();
  report.check(`asked for ${id}: a dialog or a message`, true,
    dialog ? `dialog: ${(dialog.getAttribute("aria-label") ?? dialog.textContent ?? "").trim().slice(0, 60)}`
      : `no dialog; said: ${said.slice(0, 80)}`);
  if (!shown || !dialog) return;
  if (ready) report.check(`the ${name} dialog showed what it is for`, await settle(ready, SETTLE_MS), "");
  await pause(300);
  measureControls(report, `the ${name} dialog`);
  await shot(`more-${name}`);
  const cancel = [...dialog.querySelectorAll<HTMLButtonElement>("button")]
    .find((b) => /^(Cancel|Close)$/.test((b.textContent ?? "").trim()));
  if (cancel) cancel.click();
  else dialog.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));
  const gone = await settle(() => openDialog() === undefined, 4000);
  report.check(`the ${name} dialog went away unanswered`, gone, "");
  await host.idle();
}

/**
 * States the README has no picture of, for looking at and not for publishing.
 *
 * `screenshots.py --more` asks for them: the chrome that only appears on
 * demand --- the find bar, an armed tool's row, an open menu, the text editor,
 * a failure message --- which is where a colour that does not follow the theme
 * or a row that wraps at a narrow width goes unseen. Each is a still named
 * `more-...`, and each is put away again before the next.
 */
async function moreStates(
  host: OpenCheckHost,
  shot: (name: string) => Promise<void>,
  report: Report,
): Promise<void> {
  const button = (selector: string) => document.querySelector<HTMLButtonElement>(selector);
  const escape = () =>
    window.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));

  // The find bar, with a query that matches and the results listed.
  button('button[aria-label="Find in document"]')?.click();
  await pause(200);
  const find = document.querySelector<HTMLInputElement>("input.find");
  if (find) {
    find.value = "pier";
    find.dispatchEvent(new InputEvent("input", { bubbles: true }));
    await pause(600);
    document.getElementById("tpdf-tab-results")?.click();
  }
  await shot("more-find");
  [...document.querySelectorAll<HTMLButtonElement>(".find-panel button")]
    .find((b) => b.textContent === "Close")?.click();

  // A tool armed: its status row, with the colour and width beside Cancel.
  host.run("edit.drawBox"); await host.idle();
  await shot("more-armed");
  [...document.querySelectorAll<HTMLButtonElement>(".tool-state button")]
    .find((b) => b.textContent === "Cancel")?.click();

  // A menu open, the Highlight one, which carries the swatches.
  button('button[data-group="highlight"]')?.click();
  await pause(200);
  await shot("more-menu");
  button('button[data-group="highlight"]')?.click();

  // The menu at the end of the row, which has the least room to its right.
  const last = button('button[data-group="redact"]');
  if (last && last.offsetParent !== null) {
    last.click();
    await pause(200);
    await shot("more-lastmenu");
    last.click();
  }

  // The narrow layout's More menu, when the window is narrow enough to have one.
  const narrow = button('button[data-group="More tools"]');
  if (narrow && narrow.offsetParent !== null) {
    narrow.click();
    await pause(200);
    await shot("more-narrow");
    narrow.click();
  }

  // The Document menu, which on Windows is the File menu, and the Draw menu.
  for (const group of ["document", "draw"]) {
    const opener = button(`button[data-group="${group}"]`);
    if (!opener || opener.offsetParent === null) continue;
    opener.click();
    await pause(200);
    measureControls(report, `the ${group} menu`);
    await shot(`more-${group}`);
    opener.click();
  }

  // A command found by a word its title does not have.
  [...document.querySelectorAll<HTMLButtonElement>("button")]
    .find((b) => b.textContent === "Commands")?.click();
  await pause(300);
  const field = document.querySelector<HTMLInputElement>(".tpdf-palette input");
  if (field) {
    field.value = "compress";
    field.dispatchEvent(new InputEvent("input", { bubbles: true }));
    await pause(200);
    measureControls(report, "the palette");
    await shot("more-keyword");
    field.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));
    await pause(200);
  }

  // The header's menu where there is no menu bar. Not drawn on macOS.
  const windowMenu = [...document.querySelectorAll<HTMLElement>("header details summary")]
    .find((summary) => summary.textContent === "Menu");
  if (windowMenu) {
    windowMenu.click();
    await pause(200);
    measureControls(report, "the window menu");
    await shot("more-windowmenu");
    windowMenu.click();
  }

  measureControls(report, "the window");

  // The dialogs a command opens in the window before any file is chosen: what
  // a reader is asked on the way to a smaller copy and a password. Each is
  // closed again without an answer, so nothing is written. Signing is asked
  // at the end, of a document with nothing unsaved, since it refuses this one.
  await photographDialog(host, report, shot, "file.compress", "compress");
  await photographDialog(host, report, shot, "file.protect", "password");
  // The print preview, with the marks above on its first sheet. Not on macOS,
  // where Print opens the system panel, which nothing here can close.
  if (!isMac()) {
    await photographDialog(host, report, shot, "file.print", "print", () =>
      document.querySelector(`.${PRINT_PREVIEW} img[src]`) !== null);
  }

  // A command that asks a question in the palette before it can run.
  // Reached as a reader reaches it: `host.run` refuses a command that wants
  // an answer and has none.
  [...document.querySelectorAll<HTMLButtonElement>("button")]
    .find((b) => b.textContent === "Commands")?.click();
  await pause(300);
  const question = () => document.querySelector<HTMLInputElement>(".tpdf-palette input");
  if (question()) {
    question()!.value = "dropdown";
    question()!.dispatchEvent(new InputEvent("input", { bubbles: true }));
    await pause(200);
    question()!.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }));
    await pause(300);
  }
  if (question() && question()!.offsetParent !== null) {
    question()!.value = "Yes; No; Not yet";
    question()!.dispatchEvent(new InputEvent("input", { bubbles: true }));
    await pause(200);
    measureControls(report, "the palette's question");
    await shot("more-question");
    for (let press = 0; press < 2 && question()?.offsetParent; press++) {
      question()!.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }));
      await pause(200);
    }
  }

  // The text editor's chrome over the page. It refuses while redactions are
  // pending, so the two the README's states marked are undone first.
  host.run("edit.undo"); await host.idle();
  host.run("edit.undo"); await host.idle();
  host.run("edit.editText"); await host.idle();
  await pause(600);
  await shot("more-edittext");
  escape();
  await pause(300);

  // A failure, in the colour a failure is said in.
  try {
    await host.open("/nonexistent/tpdf-screenshot-missing.pdf");
  } catch {
    // The message on screen is the point; the rejection is not.
  }
  await pause(400);
  // Read from the window, because that is the only place it can be read. The
  // wording was first applied where most messages are set, a text test of
  // that line passed, and the picture still showed `(os error 2)`.
  const problem = document.querySelector('[data-testid="problem"] p.error')?.textContent ?? "";
  report.check("a failed open is said without the operating system's number",
    problem.startsWith("Could not open") && !problem.includes("os error"), problem.slice(0, 80));
  await shot("more-problem");
}

/** The least a control may measure on either side, in CSS pixels: WCAG 2.2, 2.5.8. */
const LEAST_TARGET = 24;

/**
 * Reports the controls on screen that have no name, and those too small to hit.
 *
 * A measurement and not a verdict: both lines pass whatever they find, and say
 * what they found. Neither can be read from the source. Thirty-two buttons are
 * built in script, where no lint looks for a name, and a control's size is
 * decided by the layout it lands in.
 */
function measureControls(report: Report, where: string): void {
  const controls = [...document.querySelectorAll<HTMLElement>(
    "button, summary, input, select, textarea, [role=button], [role=tab], [role=option]",
  )].filter((control) => control.offsetParent !== null);
  const said = (control: HTMLElement) =>
    (control.textContent ?? "").trim() || control.getAttribute("aria-label") ||
    control.getAttribute("title") || control.getAttribute("placeholder") ||
    (control.id && document.querySelector(`label[for="${control.id}"]`)?.textContent) ||
    control.closest("label")?.textContent || "";
  const describe = (control: HTMLElement) =>
    `${control.tagName.toLowerCase()}${control.className ? `.${String(control.className).split(" ")[0]}` : ""}` +
    `[${(said(control) || control.dataset.testid || "?").slice(0, 24)}]`;
  const unnamed = controls.filter((control) => !said(control));
  const small = controls.filter((control) => {
    // A radio or a checkbox inside its label is pressed by pressing the label.
    const box = (control.closest("label") ?? control).getBoundingClientRect();
    return box.width < LEAST_TARGET || box.height < LEAST_TARGET;
  });
  const sizes = small.map((control) => {
    const box = control.getBoundingClientRect();
    return `${describe(control)} ${Math.round(box.width)}x${Math.round(box.height)}`;
  });
  report.check(`measured ${controls.length} controls in ${where}: unnamed`, true,
    `${unnamed.length} ${unnamed.map(describe).join(" ")}`.trim());
  report.check(`measured ${controls.length} controls in ${where}: under ${LEAST_TARGET} px`, true,
    `${small.length} ${[...new Set(sizes)].join(" ")}`.trim());
}
